            for email in acc[1:]:
                email_to_name[email] = name
                g[first].append(email)
                g[email].append(first)
        visited = set()
        res = []
        for email in email_to_name:
            if email not in visited:
                comp = []
                stack = [email]
                visited.add(email)
                while stack:
                    cur = stack.pop()
                    comp.append(cur)
                    for nxt in g[cur]:
                        if nxt not in visited:
                            visited.add(nxt)
                            stack.append(nxt)
                comp.sort()
                res.append([email_to_name[email]] + comp)
        return res

