        if (connections.length < n - 1) return -1;
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        int components = n;
        for (int[] c : connections) {
            int ru = find(parent, c[0]);
            int rv = find(parent, c[1]);
            if (ru != rv) {
                parent[ru] = rv;
                components--;
            }
        }
        return components - 1;
    }
    private int find(int[] p, int i) {
        if (p[i] == i) return i;
        return p[i] = find(p, p[i]);
    }
}

