            if x not in parent:
                parent[x] = x
                count += 1
            if x != parent[x]:
                parent[x] = find(parent[x])
            return parent[x]
        def union(x, y):
            nonlocal count
            rx, ry = find(x), find(y)
            if rx != ry:
                parent[rx] = ry
                count -= 1
        for x, y in stones:
            union(x, ~y)
        return len(stones) - count

